module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [9:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus
        clk = 0;
        reset = 0;
        #10;

        // Test reset functionality
        reset = 1;
        #20;
        reset = 0;
        #10;
        if (q !== 'b0) begin
            errors = errors + 1;
        end

        // Test counter functionality
        for (int i = 0; i < 1000; i++) begin
            #10;
            clk = ~clk;
            if (q !== i) begin
                errors = errors + 1;
            end
        end

        // Test counter wraps around
        for (int i = 1000; i < 10000; i++) begin
            #10;
            clk = ~clk;
            if (q !== (i % 1000)) begin
                errors = errors + 1;
            end
        end

        // Check if all tests pass
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
